import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RawMaterialService } from '../../services/raw-material-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule, FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-raw-material',
  imports: [CommonModule, ReactiveFormsModule, FormsModule],
  templateUrl: './add-raw-material.html',
  styleUrl: './add-raw-material.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AddRawMaterial {
  rawMaterialForm: FormGroup;

constructor(private service: RawMaterialService, private fb: FormBuilder, private router: Router) {
  this.rawMaterialForm = this.fb.group({
    name : ['', Validators.required],
    price : [ ],
  })
}
  onSubmit() {
    console.log('Submit clicked');
    if (this.rawMaterialForm.invalid) {
      this.rawMaterialForm.markAllAsTouched();
      return;
    }

    console.log('Form value:', this.rawMaterialForm.value);

    this.service.addProduct(this.rawMaterialForm.value).subscribe({
      next: () => {
        alert('✅ Raw Material created successfully');
        this.resetForm();
        this.router.navigate(['/raw-material'])
      },
      error: (err) => {
        console.error('❌ Upload failed', err);
        alert(err.error?.message || 'Upload failed. Please try again.');
      }
    });
  }

  private resetForm() {
    this.rawMaterialForm.reset();
    
  }
}
